<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']);$con->query("CREATE TABLE IF NOT EXISTS lab_requests(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT DEFAULT 0,test_name VARCHAR(150) NOT NULL,category VARCHAR(100) DEFAULT '',result TEXT,status VARCHAR(30) DEFAULT 'Pending',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,INDEX(patient_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='complete'){ $id=(int)($_POST['id']??0); $result=trim((string)($_POST['result']??'')); $u=$con->prepare("UPDATE lab_requests SET result=?,status='Completed',completed_at=NOW() WHERE id=?"); $u->bind_param('si',$result,$id); if($u->execute())$msg='Lab request completed.'; } elseif($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO lab_requests(patient_id,doctor_id,test_name,category) VALUES(?,?,?,?)");$p=(int)$_POST['patient_id'];$d=(int)($_POST['doctor_id']??0);$t=trim($_POST['test_name']);$c=trim($_POST['category']??'');$s->bind_param('iiss',$p,$d,$t,$c);if($s->execute())$msg='Lab request created.';}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$rows=$con->query("SELECT l.*,p.patientname,COALESCE(d.doctorname,'') doctorname FROM lab_requests l JOIN patient p ON p.patientid=l.patient_id LEFT JOIN doctor d ON d.doctorid=l.doctor_id ORDER BY l.id DESC LIMIT 100");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Laboratory</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">LABORATORY</span><h1>Laboratory</h1><p>Tests, requests, pending work, results and patient lab history.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="secondary-btn" href="lab_export.php">Download Excel</a></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>New lab request</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Doctor ID<input type="number" name="doctor_id" min="0"></label><label>Test name<input name="test_name" required placeholder="CBC, Blood sugar..."></label><label>Category<input name="category" placeholder="Hematology"></label><button class="primary-btn">Create request</button></form></div><div class="panel"><h2>Requests & Results</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Doctor</th><th>Test</th><th>Category</th><th>Status</th><th>Result</th><th>Date</th><th>Action</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['doctorname'])?></td><td><?=esc($r['test_name'])?></td><td><?=esc($r['category'])?></td><td><?=esc($r['status'])?></td><td><?php if($r['status']!=='Completed'):?><form method="post" style="display:flex;gap:6px;min-width:240px"><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?= (int)$r['id']?>"><input name="result" placeholder="Enter result" required><button class="secondary-btn" type="submit">Complete</button></form><?php else:?><?=esc($r['result'])?><?php endif;?></td><td><?=esc($r['requested_at'])?></td><td><?php if($r['status']==='Completed'):?><a class="secondary-btn" href="lab_print.php?id=<?= (int)$r['id']?>" target="_blank">Print</a><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
